// Wraps a managed TOM handle as KPI.
//
// Microsoft Learn:
// https://learn.microsoft.com/dotnet/api/microsoft.analysisservices.tabular.kpi?view=analysisservices-dotnet
func AsKPI(value Value) KPI { return KPI{objectRef: objectRef{Value: value}} }

// Create a new instance of the KPI class with default settings.
//
// Microsoft Learn:
// https://learn.microsoft.com/dotnet/api/microsoft.analysisservices.tabular.kpi.-ctor?view=analysisservices-dotnet
func NewKPI(client *Client) (KPI, error) {
	value, err := client.CreateExact("Microsoft.AnalysisServices.Tabular.KPI", []string{})
	return AsKPI(value), err
}

// Snapshot returns a copy of KPI with all scalar properties populated in one bridge call.
func (receiver KPI) Snapshot() (KPI, error) {
	result := receiver
	err := receiver.objectRef.Value.Snapshot([]string{"Description", "IsRemoved", "ModifiedTime", "ObjectType", "StatusDescription", "StatusExpression", "StatusGraphic", "TargetDescription", "TargetExpression", "TargetFormatString", "TrendDescription", "TrendExpression", "TrendGraphic"}, &result)
	return result, err
}

// Gets the collection object of all annotations in the current KPI.
//
// Value:
// CLR type Microsoft.AnalysisServices.Tabular.KPIAnnotationCollection.
//
// Microsoft Learn:
// https://learn.microsoft.com/dotnet/api/microsoft.analysisservices.tabular.kpi.annotations?view=analysisservices-dotnet
func (receiver KPI) Annotations() (KPIAnnotationCollection, error) {
	result, err := receiver.objectRef.Value.GetValue("Annotations")
	return AsKPIAnnotationCollection(result), err
}

// AnnotationItems gets KPI.Annotations and returns up to limit items.
func (receiver KPI) AnnotationItems(limit int) ([]Annotation, error) {
	collection, err := receiver.Annotations()
	if err != nil {
		return nil, err
	}
	if collection.TOMValue().Handle == 0 {
		return nil, nil
	}
	items, err := collection.Items(limit)
	result := make([]Annotation, len(items))
	for index := range items {
		result[index] = AsAnnotation(items[index])
	}
	return result, err
}

