// An enumeration of possible values for object state.
//
// Microsoft Learn:
// https://learn.microsoft.com/dotnet/api/microsoft.analysisservices.tabular.objectstate?view=analysisservices-dotnet
type ObjectState string

const (
	// Object is refreshed, contains up-to-date data, and is queryable.
	//
	// Microsoft Learn:
	// https://learn.microsoft.com/dotnet/api/microsoft.analysisservices.tabular.objectstate?view=analysisservices-dotnet
	ObjectStateReady ObjectState = "Ready"
	// Object is queryable but contains no data. Refresh it to bring in data. Applies to non-calculated objects,
	// such as DataColumns, partitions, and Tables.
	//
	// Microsoft Learn:
	// https://learn.microsoft.com/dotnet/api/microsoft.analysisservices.tabular.objectstate?view=analysisservices-dotnet
	ObjectStateNoData ObjectState = "NoData"
	// Object is not queryable and contains no data. It needs to be refreshed to become functional. Applies only to
	// calculated objects, such as calculated columns, hierarchies, and calculated tables.
	//
	// Microsoft Learn:
	// https://learn.microsoft.com/dotnet/api/microsoft.analysisservices.tabular.objectstate?view=analysisservices-dotnet
	ObjectStateCalculationNeeded ObjectState = "CalculationNeeded"
	// Object is in an error state because of an invalid expression. It is not queryable.
	//
	// Microsoft Learn:
	// https://learn.microsoft.com/dotnet/api/microsoft.analysisservices.tabular.objectstate?view=analysisservices-dotnet
	ObjectStateSemanticError ObjectState = "SemanticError"
	// Object is in an error state because an error occurred during expression evaluation. It is not queryable.
	//
	// Microsoft Learn:
	// https://learn.microsoft.com/dotnet/api/microsoft.analysisservices.tabular.objectstate?view=analysisservices-dotnet
	ObjectStateEvaluationError ObjectState = "EvaluationError"
	// Object is in an error state because some of its calculation dependencies are in an error state. It is not
	// queryable.
	//
	// Microsoft Learn:
	// https://learn.microsoft.com/dotnet/api/microsoft.analysisservices.tabular.objectstate?view=analysisservices-dotnet
	ObjectStateDependencyError ObjectState = "DependencyError"
	// Some parts of the object have no data. Refresh the object to add the rest of the data. The object is
	// queryable. Applies to non-calculated objects, such as DataColumns, partitions, and tables.
	//
	// Microsoft Learn:
	// https://learn.microsoft.com/dotnet/api/microsoft.analysisservices.tabular.objectstate?view=analysisservices-dotnet
	ObjectStateIncomplete ObjectState = "Incomplete"
	// The data is possibly outdated, but is in a queryable state. Applies only for CalculatedTable.
	//
	// Remarks:
	// This value is only supported at database compatibility level of 1400 or above for Pbi server.
	//
	// Microsoft Learn:
	// https://learn.microsoft.com/dotnet/api/microsoft.analysisservices.tabular.objectstate?view=analysisservices-dotnet
	ObjectStateForceCalculationNeeded ObjectState = "ForceCalculationNeeded"
)

